<script>$(function(){const tbody=$('#adjustment-lines tbody'),url='{{ route('wms.production.finished-receipts.item-options') }}',sourceRows=$('#production-source-rows'),sourceSelect=$('#production-source-select');function syncSourceNames(){sourceRows.find('tr').each(function(i){$(this).find('input[type=hidden]').attr('name','sources['+i+'][issue_id]');$(this).find('.js-source-value').attr('name','sources['+i+'][consumed_value]');});}function syncSourceTotal(){let total=0;sourceRows.find('.js-source-value').each(function(){total+=parseFloat(this.value)||0;});$('#production-source-total').text(total.toFixed({{ $valueDecimals }}));}window.erpInitSelect2(sourceSelect,{ajax:{url:sourceSelect.data('url'),delay:250,data:p=>({q:p.term||'',page:p.page||1,receipt_id:'{{ $document?->id }}'}),processResults:d=>d}});sourceSelect.on('select2:select',function(e){const d=e.params.data,id=String(d.id);if(sourceRows.find('[data-source-id="'+id+'"]').length)return;const i=sourceRows.children().length,available=d.available_value||'0';sourceRows.append('<tr data-source-id="'+id+'"><td>'+ $('<div>').text(d.text).html()+'<input type="hidden" name="sources['+i+'][issue_id]" value="'+id+'" form="adjustment-document-form"></td><td class="text-end">'+Number(available).toFixed({{ $valueDecimals }})+'</td><td><input class="form-control text-end js-source-value" type="number" min="{{ $valueStep }}" max="'+available+'" step="{{ $valueStep }}" name="sources['+i+'][consumed_value]" value="'+Number(available).toFixed({{ $valueDecimals }})+'" form="adjustment-document-form" required></td></tr>');syncSourceTotal();});sourceSelect.on('select2:unselect',function(e){sourceRows.find('[data-source-id="'+String(e.params.data.id)+'"]').remove();syncSourceNames();syncSourceTotal();});sourceRows.on('input','.js-source-value',syncSourceTotal);function syncTotal(){let total=0;tbody.find('input[name$="[value]"]').each(function(){total+=parseFloat($(this).val())||0;});$('#receipt-value-total').text(total.toFixed({{ $valueDecimals }}));}function init($s){window.erpInitSelect2($s,{ajax:{url:url,delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:d=>d}});$s.on('select2:select',e=>{const d=e.params.data,u=$s.closest('tr').find('select[name$="[uom_id]"]'),label=d.base_uom_label||'ไม่พบหน่วย Stock';u.empty().append(new Option(label,d.base_uom_id,true,true));});}$('.js-adjustment-item').each(function(){init($(this));});tbody.on('input','input[name$="[value]"]',syncTotal);$('#add-adjustment-line').on('click',function(){let i=tbody.find('tr').length;let r=$('<tr data-index="'+i+'"><td><select class="form-select js-adjustment-item" name="lines['+i+'][item_id]" required><option value="">ค้นหาสินค้า</option></select></td><td><select class="form-select" name="lines['+i+'][uom_id]" required><option value="">หน่วย Stock</option></select></td><td><input class="form-control text-end" name="lines['+i+'][quantity]" type="number" min="{{ $quantityStep }}" step="{{ $quantityStep }}" required></td><td><input class="form-control text-end" name="lines['+i+'][value]" type="number" min="{{ $valueStep }}" step="{{ $valueStep }}" required></td><td><button class="btn btn-sm btn-app-danger js-remove-line" type="button" title="ลบรายการ" aria-label="ลบรายการ"><i class="bx bx-trash" aria-hidden="true"></i></button></td></tr>');tbody.append(r);init(r.find('.js-adjustment-item'));syncTotal();});tbody.on('click','.js-remove-line',function(){if(tbody.find('tr').length>1)$(this).closest('tr').remove();syncTotal();});syncSourceTotal();syncTotal();window.erpAjaxForm({form:'#adjustment-document-form',url:$('#adjustment-document-form').attr('action'),method:'{{ $editing ? 'PUT' : 'POST' }}',redirect:true});});</script>
@endpush
